package com.gpcbellary.cms.controller; import com.gpcbellary.cms.model.CollegeRule; import com.gpcbellary.cms.repository.CollegeRuleRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/rules") @CrossOrigin public class RuleController{private final CollegeRuleRepository repo; public RuleController(CollegeRuleRepository repo){this.repo=repo;} @GetMapping public List<CollegeRule> all(){return repo.findAll();} @PostMapping public CollegeRule create(@RequestBody CollegeRule x){return repo.save(x);} @PutMapping("/{id}") public CollegeRule update(@PathVariable Long id,@RequestBody CollegeRule x){x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
